// InvoiceMutation represents an operation that mutates the Invoice nodes in the graph.
type InvoiceMutation struct {
	invoice.Mutation
	config
	id       *uuid.UUID
	done     bool
	oldValue func(context.Context) (*Invoice, error)
}

var _ ent.Mutation = (*InvoiceMutation)(nil)

// invoiceOption allows management of the mutation configuration using functional options.
type invoiceOption func(*InvoiceMutation)

// newInvoiceMutation creates new mutation for the Invoice entity.
func newInvoiceMutation(c config, op Op, opts ...invoiceOption) *InvoiceMutation {
	m := &InvoiceMutation{
		Mutation: *invoice.NewMutation(op),
		config:   c,
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// SetId sets the value of the id field. Note that this
// operation is only accepted on creation of Invoice entities.
func (m *InvoiceMutation) SetId(id uuid.UUID) {
	m.id = &id
}

// Id returns the Id value in the mutation. Note that the Id is only available
// if it was provided to the builder or after it was returned from the database.
func (m *InvoiceMutation) Id() (id uuid.UUID, exists bool) {
	if m.id == nil {
		return
	}
	return *m.id, true
}

// withInvoiceId sets the Id field of the mutation.
func withInvoiceId(id uuid.UUID) invoiceOption {
	return func(m *InvoiceMutation) {
		var (
			err   error
			once  sync.Once
			value *Invoice
		)
		m.oldValue = func(ctx context.Context) (*Invoice, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Invoice.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withInvoice sets the old Invoice of the mutation.
func withInvoice(node *Invoice) invoiceOption {
	return func(m *InvoiceMutation) {
		m.oldValue = func(context.Context) (*Invoice, error) {
			return node, nil
		}
		m.id = &node.Id
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m InvoiceMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m InvoiceMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("ent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

// Ids queries the database and returns the entity ids that match the mutation's predicate.
// That means, if the mutation is applied within a transaction with an isolation level such
// as sql.LevelSerializable, the returned ids match the ids of the rows that will be updated
// or updated by the mutation.
func (m *InvoiceMutation) Ids(ctx context.Context) ([]uuid.UUID, error) {
	switch {
	case m.Op().Is(OpUpdateOne | OpDeleteOne):
		id, exists := m.Id()
		if exists {
			return []uuid.UUID{id}, nil
		}
		fallthrough
	case m.Op().Is(OpUpdate | OpDelete):
		return m.Client().Invoice.Query().Where(m.Predicates()...).Ids(ctx)
	default:
		return nil, fmt.Errorf("Ids is not allowed on %s operations", m.Op())
	}
}

